"""Golden format (versioned JSON files in evals/goldens/*.json; generated by build_goldens.py)."""

from __future__ import annotations

import json
from pathlib import Path
from typing import Literal

from pydantic import BaseModel, Field, model_validator

from app.schemas import CaseFile

Action = Literal["FIGHT", "SETTLE", "GATHER_MORE"]
GOLDEN_VERSION = 1
DIR = Path(__file__).parent


class StoreOrder(BaseModel):
    buyer_email: str | None = None
    items: list[dict] = []
    shipping_address: dict | None = None
    invoice_id: str | None = None


class StoreShipment(BaseModel):
    carrier: str | None = None
    tracking_number: str | None = None
    status: str | None = None


class Golden(BaseModel):
    version: int = GOLDEN_VERSION
    id: str
    title: str
    source: str                      # where the case comes from (grid cell, TEST_SCENARIOS id, recorded webhook...)
    grid: dict | None = None         # {reason, strength, amount, stage} for the coverage grid
    case_file: CaseFile              # exactly what the analyst receives (built offline, no PayPal calls)
    paypal_raw: dict = {}            # the dispute JSON stored as disputes.raw (links decide allowed actions)
    order: StoreOrder | None = None  # store order (PII terms for redaction, PDF facts)
    shipments: list[StoreShipment] = []
    expected_action: Action
    acceptable_actions: list[Action] = Field(default_factory=list)  # genuinely borderline: any of these passes
    must_cite_types: list[str] = []  # evidence types the recommendation must cite (FIGHT: the proof it relies on)
    must_not_claim: list[str] = []   # phrases that must not be asserted (negated mentions are fine)
    notes: str = ""

    @model_validator(mode="after")
    def _check(self) -> "Golden":
        if self.expected_action not in self.acceptable_actions:
            self.acceptable_actions = [self.expected_action, *self.acceptable_actions]
        ids = [e.id for e in self.case_file.evidence]
        if len(ids) != len(set(ids)):
            raise ValueError(f"{self.id}: duplicate evidence ids")
        return self


def load_goldens(directory: Path = DIR) -> list[Golden]:
    goldens = [Golden.model_validate(json.loads(p.read_text())) for p in sorted(directory.glob("*.json"))]
    seen = set()
    for g in goldens:
        if g.id in seen:
            raise ValueError(f"duplicate golden id {g.id}")
        seen.add(g.id)
    return goldens
